def get_developer_title(person):
    skills = set(person.get('skills', []))
    frontend = {'JavaScript', 'React'}
    backend = {'Node', 'Python', 'MongoDB'}
    fullstack = {'React', 'Node', 'MongoDB'}
    if skills == frontend:
        return 'He is a front end developer'
    elif backend.issubset(skills):
        return 'He is a backend developer'
    elif fullstack.issubset(skills):
        return 'He is a fullstack developer'
    else:
        return 'unknown title'
